B.bkK=new A.a(69,"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0651\u0642\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0647\u0650\u0645 \u0645\u0650\u0651\u0646 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u064e\u0639\u064e\u0644\u064e\u0651\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0651\u0642\u064f\u0648\u0646\u064e","Wama AAala allatheena yattaqoona min hisabihim min shay'in walakin thikra laAAAllahum yattaqoon","Les pieux n'ont rien \xe0 r\xe9pondre de leur compte. Mais c'est un rappel, peut-\xeatre se garderont-ils.")
B.bMI=new A.a(70,"\u0648\u064e\u0630\u064e\u0631\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u064e\u0651\u062e\u064e\u0630\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u0650\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0647\u0652\u0648\u064b\u0627 \u0648\u064e\u063a\u064e\u0631\u064e\u0651\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627","Wathari allatheena ittakhathoo deenahum laAAiban walahwan wagharrat-humu alhayatu alddunya","Laisse ceux qui ont pris leur religion pour jeu et amusement et que la vie d'ici-bas a tromp\xe9s.")
B.baM=new A.a(71,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0646\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u064f\u0651\u0646\u064e\u0627 \u0648\u064e\u0646\u064f\u0631\u064e\u062f\u064f\u0651 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f","Qul anadAAoo min dooni Allahi ma la yanfaAAuna wala yadurruna wanuraddu AAala aAAqabina baAAda ith hadana Allah","Dis: \"Invoquerions-nous en dehors d'Allah ce qui ne nous profite ni ne nous nuit, et reviendrions-nous sur nos pas apr\xe8s qu'Allah nous a guid\xe9s?\"")
B.c9t=new A.a(72,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u062a\u064e\u0651\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e","Waan aqeemoo alssalata waittaqoohu wahuwa allathee ilayhi tuhsharoon","Et d'accomplir la Salat et de Le craindre. C'est Lui vers qui vous serez rassembl\xe9s.")
B.cke=new A.a(73,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0650\u0651 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651","Wahuwa allathee khalaqa alssamawati wal-arda bialhaqqi wayawma yaqoolu kun fayakoonu qawluhu alhaqqu",'C\'est Lui qui a cr\xe9\xe9 les cieux et la terre en toute v\xe9rit\xe9. Le jour o\xf9 Il dit: "Sois!" cela est. Sa parole est la v\xe9rit\xe9.')
B.aQU=new A.a(74,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0622\u0632\u064e\u0631\u064e \u0623\u064e\u062a\u064e\u062a\u064e\u0651\u062e\u0650\u0630\u064f \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064b\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0631\u064e\u0627\u0643\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0651\u0628\u0650\u064a\u0646\u064d","Wa-ith qala ibraheemu li-abeehi azara atattakhithu asnaman alihatan innee araka waqawmaka fee dalalin mubeen",'Abraham dit \xe0 son p\xe8re Azar: "Prends-tu des idoles pour divinit\xe9s? Je te vois, toi et ton peuple, dans un \xe9garement \xe9vident."')
B.bde=new A.a(75,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0631\u0650\u064a \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e","Wakathalika nuree ibraheema malakooTa alssamawati wal-ardi waliyakoona mina almuqineen","C'est ainsi que Nous faisions voir \xe0 Abraham le Royaume des cieux et de la terre afin qu'il soit parmi ceux qui ont la certitude.")
B.b3O=new A.a(76,"\u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u062c\u064e\u0646\u064e\u0651 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0644\u064e\u0651\u064a\u0652\u0644\u064f \u0631\u064e\u0623\u064e\u0649\u0670 \u0643\u064e\u0648\u0652\u0643\u064e\u0628\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0650\u0651\u064a \u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u0623\u064f\u062d\u0650\u0628\u064f\u0651 \u0627\u0644\u0652\u0622\u0641\u0650\u0644\u0650\u064a\u0646\u064e","Falamma janna AAalayhi allaYlu raa kawkaban qala hatha rabbee falamma afala qala la ohibbu al-afileen",'Quand la nuit l\'enveloppa, il vit une \xe9toile. Il dit: "Voil\xe0 mon Seigneur!" Puis quand elle disparut, il dit: "Je n\'aime pas ceux qui disparaissent."')
B.bm0=new A.a(77,"\u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0650\u0651\u064a \u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646 \u0644\u064e\u0651\u0645\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u0646\u0650\u064a \u0631\u064e\u0628\u0650\u0651\u064a \u0644\u064e\u0623\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u064e\u0651 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0636\u064e\u0651\u0627\u0644\u0650\u0651\u064a\u0646\u064e","Falamma raa alqamara bazighan qala hatha rabbee falamma afala qala la'in lam yahdinee rabbee laakoonanna mina alqawmi alddalleen",'Puis quand il vit la lune se lever, il dit: "Voil\xe0 mon Seigneur!" Quand elle disparut, il dit: "Si mon Seigneur ne me guide pas, je serai certes parmi les gens \xe9gar\xe9s."')
B.blK=new A.a(78,"\u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0634\u064e\u0651\u0645\u0652\u0633\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0650\u0651\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0641\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0623\u064e\u0641\u064e\u0644\u064e\u062a\u0652 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0650\u0651\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0651\u0645\u064e\u0651\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e","Falamma raa alshshamsa bazighatan qala hatha rabbee hatha akbaru falamma afalat qala ya qawmi innee bari'un mimma tushrikoon",'Puis quand il vit le soleil se lever, il dit: "Voil\xe0 mon Seigneur, il est plus grand!" Mais quand il disparut, il dit: "\xd4 mon peuple, je suis innocent de ce que vous associez."')
B.aVQ=new A.a(79,"\u0625\u0650\u0646\u0650\u0651\u064a \u0648\u064e\u062c\u064e\u0651\u0647\u0652\u062a\u064f \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u064e\u0651\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e","Innee wajjahtu wajhiya lillathee fatara alssamawati wal-arda haneefan wama ana mina almushrikeen",'"J\'oriente mon visage exclusivement vers Celui qui a cr\xe9\xe9 les cieux et la terre, en pur monoth\xe9iste; je ne suis pas des associateurs."')
B.c6m=new A.a(80,"\u0648\u064e\u062d\u064e\u0627\u062c\u064e\u0651\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064f\u062d\u064e\u0627\u062c\u064f\u0651\u0648\u0646\u0650\u0651\u064a \u0641\u0650\u064a \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650","Wahajjahu qawmuhu qala atuhajjoonanee fee Allahi waqad hadani wala akhafu ma tushrikoona bih","Son peuple le discuta. Il dit: \"Me disputez-vous au sujet d'Allah alors qu'Il m'a guid\xe9? Je ne crains pas ce que vous Lui associez.\"")
B.bAQ=new A.a(81,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064f\u0645 \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0650\u0651\u0644\u0652 \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627","Wakayfa akhafu ma ashraktum wala takhafoonaanna innakum ashraktum billahi ma lam yunazzil bihi AAalaykum sultana","\"Comment craindrai-je ce que vous Lui associez, alors que vous ne craignez pas d'avoir associ\xe9 \xe0 Allah ce pour quoi Il n'a fait descendre sur vous aucune preuve?\"")
B.bHr=new A.a(82,"\u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0646\u064f \u0648\u064e\u0647\u064f\u0645 \u0645\u064f\u0651\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e","Allatheena amanoo walam yalbisoo eemanahum bithulmin olaika lahumu al-amnu wahum muhtadoon","Ceux qui ont cru et n'ont pas entach\xe9 leur foi d'injustice, ceux-l\xe0 auront la s\xe9curit\xe9 et ce sont eux les bien guid\xe9s.")
