B.ass=new A.ap(28,"\u0627\u0644\u0642\u0635\u0635","Al-Qasas","Le R\xe9cit",88,B.a3Q)
B.c50=new A.a(2,"\u0623\u064e\u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f \u0623\u064e\u0646 \u064a\u064f\u062a\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u064e\u0651\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u062a\u064e\u0646\u064f\u0648\u0646\u064e","Ahasiban-n\xe2su an yutraku an yaq\xfbl\xfb \xe2mann\xe2 wa hum l\xe2 yuftan\xfbn",'Les gens pensent-ils qu\'on les laissera dire "Nous croyons" sans les \xe9prouver?')
B.br1=new A.a(3,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u062a\u064e\u0646\u064e\u0651\u0627 \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u064e\u0651 \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e","Wa laqad fatannal-ladh\xeena min qablihim, falaya'lamannAll\xe2hul-ladh\xeena sadaq\xfb wa laya'lamannal-k\xe2dhib\xeen","Nous avons certes \xe9prouv\xe9 ceux d'avant eux. Allah saura certainement ceux qui disent la v\xe9rit\xe9 et Il saura certainement les menteurs.")
B.bQQ=new A.a(4,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u064a\u0650\u0651\u0626\u064e\u0627\u062a\u0650 \u0623\u064e\u0646 \u064a\u064e\u0633\u0652\u0628\u0650\u0642\u064f\u0648\u0646\u064e\u0627 \u06da \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e","Am hasibal-ladh\xeena ya'mal\xfbnas-sayyi'\xe2ti an yasbiq\xfbn\xe2, s\xe2'a m\xe2 yahkum\xfbn","Ou bien ceux qui commettent le mal pensent-ils pouvoir Nous devancer? Comme ils jugent mal!")
B.c_L=new A.a(5,"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u064e\u0651 \u0623\u064e\u062c\u064e\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0644\u064e\u0622\u062a\u064d \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f","Man k\xe2na yarj\xfb liq\xe2'All\xe2hi fa'inna ajalAll\xe2hi la'\xe2t, wa huwas-sam\xee'ul-'al\xeem","Quiconque esp\xe8re la rencontre d'Allah... le terme fix\xe9 par Allah viendra. Il est l'Audient, l'Omniscient.")
B.biy=new A.a(6,"\u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0647\u064e\u062f\u064e \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0645\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0644\u064e\u063a\u064e\u0646\u0650\u064a\u064c\u0651 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e","Wa man j\xe2hada fa'innam\xe2 yuj\xe2hidu linafsih, innAll\xe2ha laghanniyyun 'anil-'\xe2lam\xeen","Et quiconque lutte, ne lutte que pour lui-m\xeame. Allah Se passe vraiment des mondes.")
B.bp_=new A.a(7,"\u0648\u064e\u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u064e\u0651\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0646\u064f\u0643\u064e\u0641\u0650\u0651\u0631\u064e\u0646\u064e\u0651 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0650\u0651\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0646\u064e\u0651\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e","Walladh\xeena \xe2man\xfb wa 'amiluss-s\xe2lih\xe2ti lanukaffiranna 'anhum sayyi'\xe2tihim wa lanajziyannahum ahsanal-ladh\xee k\xe2n\xfb ya'mal\xfbn","Ceux qui ont cru et accompli de bonnes \u0153uvres, Nous effacerons certainement leurs m\xe9faits et Nous les r\xe9compenserons certainement du mieux de ce qu'ils faisaient.")
B.bTk=new A.a(8,"\u0648\u064e\u0648\u064e\u0635\u064e\u0651\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u064e \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0627\u0647\u064e\u062f\u064e\u0627\u0643\u064e \u0644\u0650\u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652\u0647\u064f\u0645\u064e\u0627 \u06da \u0625\u0650\u0644\u064e\u064a\u064e\u0651 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0650\u0651\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e","Wa wassaynal-ins\xe2na biw\xe2lidayhi husn\xe2, wa in j\xe2had\xe2ka litushrika b\xee m\xe2 laysa laka bihi 'ilmun fal\xe2 tuti'hum\xe2, ilayya marji'ukum faunabi'ukum bim\xe2 kuntum ta'mal\xfbn","Nous avons enjoint \xe0 l'homme la bont\xe9 envers ses p\xe8re et m\xe8re. Mais s'ils te forcent \xe0 M'associer ce dont tu n'as aucune connaissance, ne leur ob\xe9is pas. C'est vers Moi que vous retournerez et Je vous informerai de ce que vous faisiez.")
B.aQi=new A.a(9,"\u0648\u064e\u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u064e\u0651\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u064e\u0651\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0635\u064e\u0651\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e","Walladh\xeena \xe2man\xfb wa 'amiluss-s\xe2lih\xe2ti lanudkhilannahum fis-s\xe2lih\xeen","Ceux qui ont cru et accompli de bonnes \u0153uvres, Nous les ferons certainement entrer parmi les gens de bien.")
B.buf=new A.a(10,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0622\u0645\u064e\u0646\u064e\u0651\u0627 \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0648\u0630\u0650\u064a\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u0643\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650","Wa minan-n\xe2si man yaq\xfblu \xe2mann\xe2 bill\xe2hi fa idh\xe2 \xfbdhiya fill\xe2hi ja'ala fitnatak-n\xe2si ka'adh\xe2bill\xe2h","Parmi les gens il en est qui disent: \"Nous croyons en Allah\"; puis quand ils sont \xe9prouv\xe9s \xe0 cause d'Allah, ils consid\xe8rent la pers\xe9cution des hommes comme un ch\xe2timent d'Allah.")
B.bBL=new A.a(11,"\u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u064e\u0651 \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e","Wa laya'lamannAll\xe2hul-ladh\xeena \xe2man\xfb wa laya'lamannal-mun\xe2fiq\xeen","Allah saura certes ceux qui ont cru, et Il saura certes les hypocrites.")
B.bz8=new A.a(12,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u064e\u0651\u0628\u0650\u0639\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u0652\u0646\u064e\u062d\u0652\u0645\u0650\u0644\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u062d\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0647\u064f\u0645 \u0645\u0650\u0651\u0646 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0625\u0650\u0646\u064e\u0651\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e","Wa q\xe2lal-ladh\xeena kafar\xfb lil-ladh\xeena \xe2manuttabi'\xfb sab\xeelan\xe2 walnahl khata\xe2y\xe2kum wa m\xe2 hum bih\xe2mil\xeena min khat\xe2y\xe2hum min shay'in, innahum lak\xe2dhib\xfbn",'Et les m\xe9cr\xe9ants dirent aux croyants: "Suivez notre voie et nous porterons vos fautes." Ils ne porteront rien de leurs fautes. Ce sont vraiment des menteurs.')
B.c1_=new A.a(13,"\u0648\u064e\u0644\u064e\u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0646\u064e\u0651 \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064b\u0627 \u0645\u064e\u0651\u0639\u064e \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0646\u064e\u0651 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u064e\u0645\u064e\u0651\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e","Wa layahmilunn atq\xe2lahum wa athq\xe2lan ma'a athq\xe2lihim, wa layus'alunna yawmal-qiy\xe2mati 'amm\xe2 k\xe2n\xfb yaftar\xfbn","Ils porteront certes leurs propres fardeaux et des fardeaux en plus de leurs fardeaux. Et au Jour de la R\xe9surrection ils seront interrog\xe9s sur ce qu'ils inventaient.")
B.c2K=new A.a(14,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0625\u0650\u0644\u064e\u0651\u0627 \u062e\u064e\u0645\u0652\u0633\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0637\u064f\u0651\u0648\u0641\u064e\u0627\u0646\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e","Wa laqad arsaln\xe2 N\xfbhan il\xe2 qawmihi falabitha f\xeehim alfa sanatin ill\xe2 khams\xeena '\xe2man fa'akhadhahumut-t\xfbf\xe2nu wa hum z\xe2lim\xfbn","Nous avons certes envoy\xe9 No\xe9 vers son peuple. Il demeura parmi eux mille ans moins cinquante. Le d\xe9luge les emporta alors qu'ils \xe9taient injustes.")
B.aYr=new A.a(15,"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u064e\u0651\u0641\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0651\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e","Fa'anjayn\xe2hu wa ash\xe2bas-saf\xeenati wa ja'aln\xe2h\xe2 \xe2yatan lil'\xe2lam\xeen","Nous le sauv\xe2mes lui et les gens de l'arche, et f\xeemes de celle-ci un signe pour les mondes.")
B.bSa=new A.a(16,"\u0648\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0648\u064e\u0627\u062a\u064e\u0651\u0642\u064f\u0648\u0647\u064f \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0651\u0643\u064f\u0645\u0652 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e","Wa Ibr\xe2h\xeema idh q\xe2la liqawmihi 'budull\xe2ha wattaq\xfbh, dh\xe2likum khayrun lakum in kuntum ta'lam\xfbn",'Et Abraham quand il dit \xe0 son peuple: "Adorez Allah et craignez-Le. C\'est meilleur pour vous si vous saviez."')
B.biK=new A.a(17,"\u0625\u0650\u0646\u064e\u0651\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u062a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0641\u0652\u0643\u064b\u0627 \u06da \u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0641\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0639\u0650\u0646\u062f\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0631\u0650\u0651\u0632\u0652\u0642\u064e \u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06d6 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e","Innam\xe2 ta'bud\xfbna min d\xfbnill\xe2hi awth\xe2nan wa takhluq\xfbna ifk\xe2, innal-ladh\xeena ta'bud\xfbna min d\xfbnill\xe2hi l\xe2 yamlik\xfbna lakum rizqan fabtagh\xfb 'indAll\xe2hir-rizqa wa'bud\xfbhu washkur\xfb lah, ilayhi turja'\xfbn","Vous n'adorez en dehors d'Allah que des idoles, et vous forgez des mensonges. Ceux que vous adorez en dehors d'Allah ne d\xe9tiennent aucune subsistance pour vous. Cherchez donc aupr\xe8s d'Allah la subsistance, adorez-Le et soyez-Lui reconnaissants. C'est vers Lui que vous retournerez.")
B.bHC=new A.a(18,"\u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0643\u064e\u0630\u0650\u0651\u0628\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u064e\u0651\u0628\u064e \u0623\u064f\u0645\u064e\u0645\u064c \u0645\u0650\u0651\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u064e\u0651\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f","Wa in tukadhdhib\xfb faqad kadhdhaba umumun min qablikum, wa m\xe2 'alar-ras\xfbli illal-bal\xe2ghul-mub\xeen","Si vous d\xe9mentez, des peuples avant vous ont d\xe9j\xe0 d\xe9menti. Le Messager n'a pour mission que la transmission explicite.")
B.bzX=new A.a(19,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064f\u0628\u0652\u062f\u0650\u0626\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u064e\u0651 \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u06da \u0625\u0650\u0646\u064e\u0651 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c","Awa lam yaraw kayfa yubdi'ull\xe2hul-khalqa thumma yu'\xeeduh, inna dh\xe2lika 'alAll\xe2hi yas\xeer","N'ont-ils pas vu comment Allah commence la cr\xe9ation, puis la refait? Cela est ais\xe9 pour Allah.")
B.c03=new A.a(20,"\u0642\u064f\u0644\u0652 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0628\u064e\u062f\u064e\u0623\u064e \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u06da \u062b\u064f\u0645\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u064a\u064f\u0646\u0634\u0650\u0626\u064f \u0627\u0644\u0646\u064e\u0651\u0634\u0652\u0623\u064e\u0629\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06da \u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c","Qul s\xeer\xfb fil-ardi fanzur\xfb kayfa bada'al-khalqa, thummAll\xe2hu yunshi'un-nash'atal-\xe2khirata, innAll\xe2ha 'al\xe2 kulli shay'in qad\xeer",'Dis: "Parcourez la terre et observez comment Il a commenc\xe9 la cr\xe9ation. Ensuite Allah renouvellera la cr\xe9ation finale. Allah est certes Omnipotent."')
B.buN=new A.a(21,"\u064a\u064f\u0639\u064e\u0630\u0650\u0651\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0642\u0652\u0644\u064e\u0628\u064f\u0648\u0646\u064e","Yu'adhdhibu man yash\xe2'u wa yarhamun man yash\xe2'u, wa ilayhi tuqlab\xfbn","Il ch\xe2tie qui Il veut et fait mis\xe9ricorde \xe0 qui Il veut. Et c'est vers Lui que vous serez ramen\xe9s.")
B.bMn=new A.a(22,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0650\u0651\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u064d\u0651 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d","Wa m\xe2 antum bim\xfa'jiz\xeena fil-ardi wa l\xe2 fis-sam\xe2'i wa m\xe2 lakum min d\xfbnill\xe2hi min waliyyin wa l\xe2 nas\xeer","Vous ne pouvez r\xe9duire Allah \xe0 l'impuissance ni sur terre ni dans le ciel. Vous n'avez en dehors d'Allah ni protecteur ni secoureur.")
B.aQQ=new A.a(23,"\u0648\u064e\u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0626\u0650\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0626\u0650\u0633\u064f\u0648\u0627 \u0645\u0650\u0646 \u0631\u064e\u0651\u062d\u0652\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c","Walladh\xeena kafar\xfb bi'\xe2y\xe2till\xe2hi wa liq\xe2'ihi ul\xe2'ika ya'is\xfb min rahmat\xee wa ul\xe2'ika lahum 'adh\xe2bun al\xeem","Ceux qui ne croient pas aux signes d'Allah et \xe0 la rencontre avec Lui, ceux-l\xe0 d\xe9sesp\xe8rent de Ma mis\xe9ricorde, et ceux-l\xe0 auront un ch\xe2timent douloureux.")
B.bXT=new A.a(24,"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0651\u0627 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u0652 \u062d\u064e\u0631\u0650\u0651\u0642\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u062c\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u06da \u0625\u0650\u0646\u064e\u0651 \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0651\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e","Fam\xe2 k\xe2na jaw\xe2ba qawmihi ill\xe2 an q\xe2l\xfbqtul\xfbhu aw harriq\xfbhu fa'anj\xe2hull\xe2hu minan-n\xe2ri, inna f\xee dh\xe2lika la'\xe2y\xe2tin liqawmin yu'min\xfbn",'La r\xe9ponse de son peuple ne fut que de dire: "Tuez-le ou br\xfblez-le!" Mais Allah le sauva du feu. Il y a l\xe0 vraiment des signes pour des gens qui croient.')
B.b4i=new A.a(25,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u064e\u0651\u0645\u064e\u0627 \u0627\u062a\u064e\u0651\u062e\u064e\u0630\u0652\u062a\u064f\u0645 \u0645\u0650\u0651\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u064b\u0627 \u0645\u064e\u0651\u0648\u064e\u062f\u064e\u0651\u0629\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u06d6 \u062b\u064f\u0645\u064e\u0651 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u064a\u064e\u0644\u0652\u0639\u064e\u0646\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0650\u0651\u0646 \u0646\u064e\u0651\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e","Wa q\xe2la innamattakhadhtum min d\xfbnill\xe2hi awth\xe2nan mawaddata baynikum fil-hay\xe2tid-duny\xe2, thumma yawmal-qiy\xe2mati yakfuru ba'dhukum biba'dhin wa yal'anu ba'dhukum ba'dhan wa ma'w\xe2kumun-n\xe2ru wa m\xe2 lakum min n\xe2sir\xeen","Et il dit: \"Vous n'avez pris, en dehors d'Allah, que des idoles, par affection entre vous dans la vie pr\xe9sente. Puis au Jour de la R\xe9surrection, vous vous renierez mutuellement et vous vous maudirez les uns les autres. Votre refuge sera le Feu. Vous n'aurez aucun secoureur.\"")
B.brO=new A.a(26,"\u0641\u064e\u0622\u0645\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0644\u064f\u0648\u0637\u064c \u06d8 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0650\u0651\u064a \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0650\u0651\u064a \u06d6 \u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f","Fa'\xe2mana lah\xfb L\xfbt, wa q\xe2la inn\xee muh\xe2jirun il\xe2 rabb\xee, innahu huwal-'az\xeezul-hak\xeem","Loth crut en lui. Et il dit: \"Je fais l'\xe9migration vers mon Seigneur. C'est Lui le Puissant, le Sage.\"")
B.b9g=new A.a(27,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0630\u064f\u0631\u0650\u0651\u064a\u064e\u0651\u062a\u0650\u0647\u0650 \u0627\u0644\u0646\u064f\u0651\u0628\u064f\u0648\u064e\u0651\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e","Wa wahabn\xe2 lah\xfb Ish\xe2qa wa Ya'q\xfbba wa ja'aln\xe2 f\xee dhurriyyatihinnubuwwata wal-kit\xe2ba wa \xe2tayn\xe2hu ajrahu fid-duny\xe2, wa innahu fil-\xe2khirati laminas-s\xe2lih\xeen","Et Nous lui accord\xe2mes Isaac et Jacob, et pla\xe7\xe2mes dans sa descendance la proph\xe9tie et le Livre. Nous lui donn\xe2mes sa r\xe9compense ici-bas; et dans l'au-del\xe0, il sera certes parmi les gens de bien.")
B.bSP=new A.a(28,"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0651\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e","Wa L\xfbtan idh q\xe2la liqawmihi innakum lata't\xfbnal-f\xe2hishata m\xe2 sabaqakum bih\xe2 min ahadin minal-'\xe2lam\xeen","Et Loth quand il dit \xe0 son peuple: \"Vous commettez vraiment la turpitude qu'aucun \xeatre au monde n'a commise avant vous.\"")
B.cju=new A.a(29,"\u0623\u064e\u0626\u0650\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0650\u0651\u062c\u064e\u0627\u0644\u064e \u0648\u064e\u062a\u064e\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u0628\u0650\u064a\u0644\u064e \u0648\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0646\u064e\u0627\u062f\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0643\u064e\u0631\u064e \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0651\u0627 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0626\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e","A'innakum lata't\xfbnar-rij\xe2la wa taqta'\xfbnas-sab\xeela wa ta't\xfbna f\xee n\xe2d\xeekumul-munkar, fam\xe2 k\xe2na jaw\xe2ba qawmihi ill\xe2 an q\xe2l\xfbtu'n\xe2 bi'adh\xe2bill\xe2hi in kunta minas-s\xe2diq\xeen","Est-ce que vous vous approchez vraiment des hommes, coupez la route et commettez l'acte r\xe9pr\xe9hensible dans vos assembl\xe9es? La r\xe9ponse de son peuple ne fut que de dire: \"Apporte-nous le ch\xe2timent d'Allah si tu es du nombre des v\xe9ridiques.\"")
B.aRX=new A.a(30,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0650\u0651 \u0627\u0646\u0635\u064f\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e","Q\xe2la rabbinsurn\xee 'alal-qawmil-mufsid\xeen",'Il dit: "Seigneur, donne-moi la victoire contre le peuple corrupteur."')
B.byf=new A.a(31,"\u0648\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u064e\u0651\u0627 \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648 \u0623\u064e\u0647\u0652\u0644\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u06d6 \u0625\u0650\u0646\u064e\u0651 \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e","Wa lamm\xe2 j\xe2'at rusulun\xe2 Ibr\xe2h\xeema bil-bushr\xe2 q\xe2l\xfb inn\xe2 muhlik\xfb ahli h\xe2dhihil-qaryati, inna ahla h\xe2 k\xe2n\xfb z\xe2lim\xeen",'Lorsque Nos envoy\xe9s vinrent apporter la bonne nouvelle \xe0 Abraham, ils dirent: "Nous allons d\xe9truire les habitants de cette cit\xe9. Ses habitants sont vraiment des injustes."')
B.cbf=new A.a(32,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u064e\u0651 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064f\u0648\u0637\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0644\u064e\u0646\u064f\u0646\u064e\u062c\u0650\u0651\u064a\u064e\u0646\u064e\u0651\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e","Q\xe2la inna f\xeeh\xe2 L\xfbtan, q\xe2l\xfb nahnu a'lamu biman f\xeeh\xe2, lanunajjiyannah\xfb wa ahlahu ill\xe2mra'atahu k\xe2nat minal-gh\xe2bir\xeen",'Il dit: "Loth s\'y trouve." Ils dirent: "Nous savons fort bien qui s\'y trouve. Nous le sauverons certes lui et sa famille, sauf sa femme qui sera du nombre de ceux qui resteront."')
B.c1H=new A.a(33,"\u0648\u064e\u0644\u064e\u0645\u064e\u0651\u0627 \u0623\u064e\u0646 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064f\u0648\u0637\u064b\u0627 \u0633\u0650\u064a\u0621\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0636\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0630\u064e\u0631\u0652\u0639\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u06d6 \u0625\u0650\u0646\u064e\u0651\u0627 \u0645\u064f\u0646\u064e\u062c\u064f\u0651\u0648\u0643\u064e \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0643\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e","Wa lamm\xe2 an j\xe2'at rusulun\xe2 L\xfbtan s\xee'a bihim wa dh\xe2qa bihim dhar'an wa q\xe2l\xfb l\xe2 takhaf wa l\xe2 tahzan, inn\xe2 munajj\xfbka wa ahlaka ill\xe2mra'ataka k\xe2nat minal-gh\xe2bir\xeen","Lorsque Nos envoy\xe9s arriv\xe8rent chez Loth, il fut afflig\xe9 \xe0 cause d'eux et se sentit impuissant \xe0 les prot\xe9ger. Ils dirent: \"N'aie pas peur et ne t'afflige pas. Nous te sauverons toi et ta famille, sauf ta femme qui sera du nombre de ceux qui resteront.\"")
B.c9q=new A.a(34,"\u0625\u0650\u0646\u064e\u0651\u0627 \u0645\u064f\u0646\u0632\u0650\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0631\u0650\u062c\u0652\u0632\u064b\u0627 \u0645\u0650\u0651\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e","Inn\xe2 munzil\xfbna 'al\xe2 ahli h\xe2dhihil-qaryati rijzan minas-sam\xe2'i bim\xe2 k\xe2n\xfb yafsuq\xfbn","Nous allons faire descendre sur les habitants de cette cit\xe9 un ch\xe2timent venu du ciel, \xe0 cause de leur perversit\xe9.")
B.b0e=new A.a(35,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f \u062a\u064e\u0651\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0628\u064e\u064a\u0650\u0651\u0646\u064e\u0629\u064b \u0644\u0650\u0651\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e","Wa laqad tarakn\xe2 minh\xe2 \xe2yatan bayyinatan liqawmin ya'qil\xfbn","Nous en avons certes laiss\xe9 un signe \xe9vident pour des gens qui raisonnent.")
B.aSg=new A.a(36,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0648\u064e\u0627\u0631\u0652\u062c\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e","Wa il\xe2 Madyana akh\xe2hum Shu'ayban faq\xe2la y\xe2 qawmi'budull\xe2ha warjul-yawmal-\xe2khira wa l\xe2 ta'thaw fil-ardi mufsid\xeen",'Et vers Madyan, leur fr\xe8re Chuayb. Il dit: "\xd4 mon peuple, adorez Allah et esp\xe9rez le Jour Dernier. Ne semez pas la corruption sur la terre."')
