B.afO=new A.bg(B.fm,["\u0648\u064e\u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0639\u0652\u0637\u0650\u064a\u0643\u064e \u0631\u064e\u0628\u064f\u0651\u0643\u064e \u0641\u064e\u062a\u064e\u0631\u0652\u0636\u064e\u0649\u0670","\xab Ton Seigneur t'accordera tant que tu seras satisfait. \xbb","Ad-Duha \xb7 93:5"],t.l)
B.afT=new A.bg(B.fm,["\u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e","\xab Allah est avec les patients. \xbb","Al-Baqara \xb7 2:153"],t.l)
B.afQ=new A.bg(B.fm,["\u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652","\xab Il est avec vous o\xf9 que vous soyez. \xbb","Al-Hadid \xb7 57:4"],t.l)
B.afR=new A.bg(B.fm,["\u0631\u064e\u0628\u0650\u0651 \u0627\u0634\u0652\u0631\u064e\u062d\u0652 \u0644\u0650\u064a \u0635\u064e\u062f\u0652\u0631\u0650\u064a","\xab Seigneur, ouvre-moi ma poitrine. \xbb","Ta-Ha \xb7 20:25"],t.l)
